359:        match std::fs::canonicalize(&probe) {
360:            Ok(c) => break c,
361:            // `NotADirectory` means a component partway down the path is a
362:            // regular file, so the target does not exist — exactly what
363:            // `NotFound` means for this walk, and NOT evidence of an escape.
364:            // Unix reports ENOTDIR here where Windows reports not-found, and
365:            // treating that difference as a containment violation made a
366:            // per-file mkdir failure session-FATAL on Unix only: a tar-shard
