444:        path.to_path_buf()
445:    } else {
446:        std::env::current_dir()
447:            .with_context(|| format!("resolve current_dir for '{}'", path.display()))?
448:            .join(path)
449:    };
450:
451:    let mut resolved = PathBuf::new();
452:    for comp in abs.components() {
453:        match comp {
454:            Component::Prefix(p) => resolved.push(p.as_os_str()),
455:            Component::RootDir => resolved.push(comp.as_os_str()),
456:            Component::CurDir => {}
457:            Component::Normal(name) => resolved.push(name),
458:            Component::ParentDir => {
459:                let canon_prefix = std::fs::canonicalize(&resolved).map_err(|e| {
460:                    eyre::eyre!(
461:                        "path '{}' contains '..' component over non-canonicalizable prefix '{}': {}",
