463:                        resolved.display(),
464:                        e
465:                    )
466:                })?;
467:                resolved = canon_prefix;
468:                if !resolved.pop() {
469:                    bail!(
470:                        "path '{}' traverses above filesystem root via '..'",
471:                        path.display()
472:                    );
473:                }
474:            }
475:        }
476:    }
