478:    let mut probe = resolved;
479:    let mut tail: Vec<std::ffi::OsString> = Vec::new();
480:    let canonical_ancestor = loop {
481:        match std::fs::canonicalize(&probe) {
482:            Ok(c) => break c,
483:            Err(e)
484:                if matches!(
485:                    e.kind(),
486:                    std::io::ErrorKind::NotFound | std::io::ErrorKind::NotADirectory
487:                ) =>
488:            {
489:                let Some(Component::Normal(name)) = probe.components().next_back() else {
490:                    bail!(
491:                        "destination root '{}' has no canonicalizable \
492:                         ancestor — filesystem root unreachable",
493:                        path.display()
494:                    );
495:                };
496:                tail.push(name.to_os_string());
497:                if !probe.pop() {
498:                    bail!(
499:                        "destination root '{}' has no canonicalizable \
