9:/// Available checksum algorithms
10:#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
11:pub enum ChecksumType {
12:    #[default]
13:    Blake3,
14:    XxHash3,
15:    Md5, // For compatibility
16:}
17:
18:/// CHAR_OFFSET constant from rsync (for compatibility)
19:const CHAR_OFFSET: u32 = 31;
20:
21:/// Fast rolling checksum implementation (based on rsync's get_checksum1)
22:/// This implements the same algorithm as rsync for compatibility
23:/// Rolling checksum state: `s1` and `s2` are the Adler-style accumulators
24:/// used by the rsync-compatible algorithm. `block_size` is the window size
25:/// (in bytes) for rolling operations and must fit in `u32`.
26:pub struct RollingChecksum {
27:    s1: u32,
28:    s2: u32,
29:    block_size: u32,
30:}
31:
32:impl RollingChecksum {
33:    pub fn new(block_size: usize) -> Result<Self> {
34:        let bs: u32 = block_size.try_into().with_context(|| {
35:            format!(
36:                "block_size {} exceeds u32::MAX for rolling checksum",
37:                block_size
38:            )
39:        })?;
40:        Ok(Self {
41:            s1: 0,
42:            s2: 0,
43:            block_size: bs,
44:        })
45:    }
46:
47:    /// Initialize checksum for a block of data (rsync-compatible)
48:    pub fn init(&mut self, data: &[u8]) {
49:        self.s1 = 0;
50:        self.s2 = 0;
51:
52:        // Use rsync's algorithm: process 4 bytes at a time for speed
53:        let (chunks, remainder) = data.as_chunks::<4>();
54:        for &[b0, b1, b2, b3] in chunks {
55:            let b0 = b0 as u32;
56:            let b1 = b1 as u32;
57:            let b2 = b2 as u32;
58:            let b3 = b3 as u32;
59:
60:            self.s2 = self.s2.wrapping_add(
61:                4u32.wrapping_mul(self.s1.wrapping_add(b0))
62:                    .wrapping_add(3u32.wrapping_mul(b1))
63:                    .wrapping_add(2u32.wrapping_mul(b2))
64:                    .wrapping_add(b3)
65:                    .wrapping_add(10u32.wrapping_mul(CHAR_OFFSET)),
66:            );
67:
68:            self.s1 = self.s1.wrapping_add(
69:                b0.wrapping_add(b1)
70:                    .wrapping_add(b2)
71:                    .wrapping_add(b3)
72:                    .wrapping_add(4u32.wrapping_mul(CHAR_OFFSET)),
73:            );
74:        }
75:
76:        // Process remaining bytes
77:        for &byte in remainder {
78:            let v = byte as u32;
79:            self.s1 = self.s1.wrapping_add(v.wrapping_add(CHAR_OFFSET));
80:            self.s2 = self.s2.wrapping_add(self.s1);
81:        }
82:    }
83:
84:    /// Roll the checksum by removing old byte and adding new byte
85:    pub fn roll(&mut self, old_byte: u8, new_byte: u8) {
86:        let old = old_byte as u32 + CHAR_OFFSET;
87:        let new = new_byte as u32 + CHAR_OFFSET;
88:
89:        self.s1 = self.s1.wrapping_sub(old).wrapping_add(new);
90:        self.s2 = self
91:            .s2
92:            .wrapping_sub(self.block_size * old)
93:            .wrapping_add(self.s1);
94:    }
95:
96:    /// Get current checksum value (rsync format: s1 in lower 16 bits, s2 in upper 16 bits)
97:    pub fn value(&self) -> u32 {
98:        (self.s1 & 0xFFFF) | (self.s2 << 16)
99:    }
100:}
