107:impl RollingChecksum {
108:    /// Convenience method: compute the rolling checksum for a slice
109:    pub fn compute(data: &[u8]) -> Result<u32> {
110:        let mut checksum = RollingChecksum::new(data.len())?;
111:        checksum.init(data);
112:        Ok(checksum.value())
113:    }
114:}
115:
116:/// Compute strong checksum for data
117:pub fn strong_checksum(
118:    data: &[u8],
119:    checksum_type: ChecksumType,
120:    allow_md5: bool,
121:) -> Result<Vec<u8>> {
122:    match checksum_type {
123:        ChecksumType::Blake3 => {
124:            let hash = blake3::hash(data);
125:            Ok(hash.as_bytes().to_vec())
126:        }
127:        ChecksumType::XxHash3 => {
128:            let h = xxhash_rust::xxh3::xxh3_64(data);
129:            Ok(h.to_be_bytes().to_vec())
130:        }
131:        ChecksumType::Md5 => {
132:            // SECURITY WARNING: MD5 is cryptographically broken
133:            if !allow_md5 {
134:                bail!("MD5 is disabled; enable explicitly to use for compatibility");
135:            }
136:            warn!("MD5 is cryptographically broken; prefer Blake3 (default) or SHA-256");
137:            Ok(md5::compute(data).to_vec())
138:        }
139:    }
140:}
