142:/// Buffer size for streaming hashing — the one place this decision
143:/// lives (w7-4: it was restated at five sites, including a 256 KiB
144:/// stack array in the daemon's `build_file_header`).
145:const HASH_READ_BUF_BYTES: usize = 256 * 1024;
146:
147:/// Hash everything `reader` yields with the given algorithm, owning
148:/// the read loop and buffer size. `hash_file`, `partial_hash_first_last`'s
149:/// small-file branch, and the daemon's `build_file_header` (which has an
150:/// already-open `File` that `hash_file`'s path signature can't accept)
151:/// all route through here.
152:pub fn hash_reader(reader: &mut dyn Read, ty: ChecksumType) -> Result<Vec<u8>> {
153:    let mut buf = vec![0u8; HASH_READ_BUF_BYTES];
154:    match ty {
155:        ChecksumType::Blake3 => {
156:            let mut hasher = blake3::Hasher::new();
157:            loop {
158:                let n = reader.read(&mut buf)?;
159:                if n == 0 {
160:                    break;
161:                }
162:                hasher.update(&buf[..n]);
163:            }
164:            Ok(hasher.finalize().as_bytes().to_vec())
165:        }
166:        ChecksumType::XxHash3 => {
167:            let mut state = xxhash_rust::xxh3::Xxh3::new();
168:            loop {
169:                let n = reader.read(&mut buf)?;
170:                if n == 0 {
171:                    break;
172:                }
173:                state.update(&buf[..n]);
174:            }
175:            Ok(state.digest().to_be_bytes().to_vec())
176:        }
177:        ChecksumType::Md5 => {
178:            let mut ctx = md5::Context::new();
179:            loop {
180:                let n = reader.read(&mut buf)?;
181:                if n == 0 {
182:                    break;
183:                }
184:                ctx.consume(&buf[..n]);
185:            }
186:            Ok(ctx.finalize().to_vec())
187:        }
188:    }
189:}
