191:/// cr-ecm29-4, cr-ecm30-5: a file opened to be hashed — without waiting, so
192:/// a FIFO put in its place after a look cannot hold the open — and only if
193:/// what was opened is a regular file. Opened to be read, a FIFO waited for a
194:/// writer, and the comparison with it: the local `--checksum` copy's, the
195:/// wire's, `check`'s. One opener for every comparison that hashes a file.
196:pub(crate) fn open_regular_file(path: &Path) -> Result<File> {
197:    let mut open = std::fs::OpenOptions::new();
198:    open.read(true);
199:    #[cfg(unix)]
200:    {
201:        use std::os::unix::fs::OpenOptionsExt as _;
202:        open.custom_flags(libc::O_NONBLOCK);
203:    }
204:    let file = open
205:        .open(path)
206:        .with_context(|| format!("open {}", path.display()))?;
207:    let found = file
208:        .metadata()
209:        .with_context(|| format!("looking at {}", path.display()))?;
210:    if !found.is_file() {
211:        eyre::bail!("{} is not a regular file", path.display());
212:    }
213:    Ok(file)
214:}
215:
216:/// Hash a whole file with the given algorithm — opened through
217:/// [`open_regular_file`].
218:pub fn hash_file(path: &Path, ty: ChecksumType) -> Result<Vec<u8>> {
219:    let mut f = open_regular_file(path)?;
220:    hash_reader(&mut f, ty)
221:}
222:
223:/// Compute a partial hash consisting of the first and last `bytes` of the file using BLAKE3.
224:/// If the file is smaller than 2*bytes, the whole file is hashed.
225:pub fn partial_hash_first_last(path: &Path, bytes: usize) -> Result<Vec<u8>> {
226:    let mut f = open_regular_file(path)?;
227:    let len = f.metadata()?.len();
228:    if len as usize <= bytes * 2 {
229:        // Whole-file Blake3 — identical to hash_reader's Blake3 arm.
230:        return hash_reader(&mut f, ChecksumType::Blake3);
231:    }
232:    let mut hasher = blake3::Hasher::new();
233:    let mut first = vec![0u8; bytes];
234:    f.read_exact(&mut first)?;
235:    hasher.update(b"FIRST");
236:    hasher.update(&first);
237:
238:    f.seek(SeekFrom::End(-(bytes as i64)))?;
239:    let mut last = vec![0u8; bytes];
240:    f.read_exact(&mut last)?;
241:    hasher.update(b"LAST");
242:    hasher.update(&last);
243:    hasher.update(&len.to_le_bytes());
244:    Ok(hasher.finalize().as_bytes().to_vec())
245:}
