#[cfg(all(test, unix))]
#[test]
fn review_r32_reports_a_partial_left_when_cleanup_is_refused() {
    use std::os::unix::fs::PermissionsExt;
    let fixture = tempfile::tempdir().unwrap();
    let path = fixture.path().join("destination");
    let err = fresh_partial_ready(&path, 19, None, |_| -> Result<()> {
        std::fs::set_permissions(fixture.path(), std::fs::Permissions::from_mode(0o555))?;
